-- PT120-S1-Q4. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT120-S1-Q4$batch07$ AND q.stimulus=$batch07$Aaron: A prominent judge, criticizing “famous lawyers who come before courts ill-prepared to argue their cases, ” recently said, “This sort of cavalier attitude offends the court and can do nothing but harm to the client’s cause.” I find the judge’s remarks irresponsible.
Belinda: I find it natural and an admirable display of candor. Letting people know of the damage their negligence causes is responsible behavior.$batch07$ AND q.prompt=$batch07$The point at issue between Aaron and Belinda is whether$batch07$ AND q.correct_choice=$batch07$B$batch07$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT120-S1-Q4$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S1-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT120-S1-Q4$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Aaron's Position$batch07$, $batch07$The judge's remarks were irresponsible.$batch07$), (1, $batch07$Belinda's Position$batch07$, $batch07$The remarks were natural and admirable. Telling people about the damage their negligence causes is responsible behavior.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$This is as direct as these get. Aaron calls the remarks irresponsible; Belinda calls them responsible. Aaron never says the judge was wrong about the facts, only that saying it was irresponsible. So stay with the one word they fight over.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether the judge's criticism was irresponsible.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT120-S1-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Belinda implies ill-prepared lawyers do damage. Aaron never disputes that; Aaron objects to the judge saying it.$batch07$), ($batch07$B$batch07$, $batch07$Aaron: "irresponsible". Belinda: "responsible behavior". Opposite sides, both stated.$batch07$), ($batch07$C$batch07$, $batch07$Belinda calls it negligence. Aaron says nothing about whether being ill-prepared is negligent.$batch07$), ($batch07$D$batch07$, $batch07$Neither speaker compares famous lawyers with other lawyers.$batch07$), ($batch07$E$batch07$, $batch07$The judge says ill-prepared lawyers offend the court. Neither Aaron nor Belinda takes a position on whether that is to be expected.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT120-S1-Q4$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
